import java.io.IOException;
import java.util.Properties;

public class DatabaseConfigLoader {
    private static final Properties properties;
    private static final String connectionUrl;

    static {
        properties = new Properties();
        try {
            // Complex I/O initialization requiring static context
            properties.load(DatabaseConfigLoader.class.getResourceAsStream("/db.properties"));
            connectionUrl = properties.getProperty("db.url");
            if (connectionUrl == null) {
                throw new IllegalStateException("Database URL configuration is missing.");
            }
        } catch (IOException e) {
            // Encapsulate checked exceptions into an unrecoverable initialization error
            throw new ExceptionInInitializerError(e);
        }
    }

    public static String getConnectionUrl() {
        return connectionUrl;
    }
}
